#!/usr/bin/env python3
"""Generate typed simple-case maps from the selected upstream R source checkout."""
import argparse
import hashlib
from pathlib import Path
import re
import subprocess


def generate(source: Path) -> str:
    revision = subprocess.check_output(
        ["git", "-C", str(source), "rev-parse", "HEAD"], text=True
    ).strip()
    lines = [
        "// Generated by scripts/generate_unicode_case_tables.py; do not edit.",
        "// Mapping data Copyright (C) 2020-2026 The R Core Team.",
        "// SPDX-License-Identifier: GPL-2.0-or-later",
        f"// Upstream R source commit: {revision}",
        "#![forbid(unsafe_code)]",
    ]
    version = None
    for direction in ["upper", "lower"]:
        name = f"src/main/rlocale_to{direction}.h"
        data = (source / name).read_bytes()
        text = data.decode("utf-8")
        current = re.search(r"Unicode ([0-9.]+) tables", text).group(1)
        if version is not None and current != version:
            raise ValueError("upper/lower Unicode versions differ")
        version = current
        pairs = [tuple(int(value, 16) for value in pair) for pair in
                 re.findall(r"\{\s*0x([0-9A-Fa-f]+)\s*,\s*0x([0-9A-Fa-f]+)\s*\}", text)]
        if not pairs or pairs != sorted(pairs) or len({p[0] for p in pairs}) != len(pairs):
            raise ValueError(f"{name}: expected sorted unique case keys")
        if any(not (0 <= cp <= 0x10FFFF) or 0xD800 <= cp <= 0xDFFF
               for pair in pairs for cp in pair):
            raise ValueError(f"{name}: non-scalar case mapping")
        lines.extend([
            "", f"// Upstream generated Unicode version: {version}",
            f"// {name}: SHA256 {hashlib.sha256(data).hexdigest()}",
            f"pub(super) const {direction.upper()}: &[(char, char)] = &[",
        ])
        lines.extend(f"    ('\\u{{{first:x}}}', '\\u{{{second:x}}}')," for first, second in pairs)
        lines.append("];")
    formatted = subprocess.run(
        ["rustfmt", "--edition", "2024", "--config", "skip_children=true"],
        input="\n".join(lines) + "\n", capture_output=True, text=True, check=True
    )
    return formatted.stdout


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-root", type=Path, default=Path("r-source"))
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = Path("crates/rmath/src/mainutils/rlocale/case_tables.rs")
    text = generate(args.source_root)
    if args.check:
        if not output.exists() or output.read_text() != text:
            raise SystemExit(f"{output}: generated data differs")
        print(f"{output}: verified")
    else:
        output.write_text(text)
        print(f"{output}: generated")


if __name__ == "__main__":
    main()
